<?php

declare(strict_types=1);

namespace WPJarvis\Framework\Console\Commands\Cache;

use Illuminate\Console\Command;

/**
 * Base Cache Command
 *
 * Provides shared functionality for cache generation commands.
 *
 * @package WPJarvis\Framework\Console\Commands\Cache
 */
abstract class BaseCacheCommand extends Command
{
    /**
     * Ensure the cache directory exists.
     *
     * @return bool True if a directory exists or was created successfully.
     */
    protected function ensureCacheDirectoryExists(): bool
    {
        $cacheDir = $this->laravel->bootstrapPath('cache');

        if (!is_dir($cacheDir)) {
            $created = mkdir($cacheDir, 0755, true);

            if (!$created) {
                $this->error("Failed to create cache directory: {$cacheDir}");

                return false;
            }

            $this->verbose("Created cache directory: {$cacheDir}");
        }

        return true;
    }

    /**
     * Export cache data to a PHP file.
     *
     * @param string $path Cache file path.
     * @param mixed $data Data to cache.
     * @param string $type Cache type for header comment.
     *
     * @return bool True if export was successful.
     */
    protected function exportCache(string $path, mixed $data, string $type): bool
    {
        $header = $this->generateCacheHeader($type);

        $export = var_export($data, true);

        $content = <<<CONTENT
<?php
{$header}

return {$export};

CONTENT;

        $written = file_put_contents($path, $content);

        if ($written === false) {
            $this->error("Failed to write cache file: {$path}");

            return false;
        }

        // Verify the file was written and can be read
        if (!file_exists($path) || !is_readable($path)) {
            $this->error("Cache file was written but is not readable: {$path}");

            return false;
        }

        return true;
    }

    /**
     * Generate cache file header comment.
     *
     * @param string $type Cache type (e.g., 'Configuration', 'Routes', 'Events').
     *
     * @return string Header comment.
     */
    private function generateCacheHeader(string $type): string
    {
        $timestamp = date('Y-m-d H:i:s');
        $command = strtolower(str_replace(' ', '', $type));

        return <<<COMMENT
/**
 * Cached {$type} File
 *
 * This file was generated by WP-Jarvis framework.
 * DO NOT modify this file manually.
 *
 * Generated: {$timestamp}
 *
 * To regenerate, run: wp jarvis {$command}:cache
 * To clear, run: wp jarvis cache:clear --{$command}
 */
COMMENT;
    }

    /**
     * Display caching header.
     *
     * @param string $type Cache type (e.g., 'Configuration', 'Routes').
     *
     * @return void
     */
    protected function displayCachingHeader(string $type): void
    {
        $this->info("{$type} Caching");
        $this->info(str_repeat('=', strlen("{$type} Caching")));
        $this->newLine();
        $this->info("Caching {$type} definitions...");
        $this->newLine();
    }

    /**
     * Display success message with a cache file path.
     *
     * @param string $path Cache file path.
     * @param int $count Number of items cached.
     * @param string $type Cache type.
     *
     * @return void
     */
    protected function displayCacheSuccess(string $path, int $count, string $type): void
    {
        $this->newLine();
        $this->info('Summary');
        $this->info('-------');
        $this->info(sprintf(
            '<comment>%d</comment> %s cached successfully',
            $count,
            $type
        ));
        $this->newLine();

        $relativePath = str_replace(
            $this->laravel->basePath() . DIRECTORY_SEPARATOR,
            '',
            $path
        );

        $this->info(sprintf(
            'Cached successfully to: <comment>%s</comment>',
            $relativePath
        ));
    }

    /**
     * Warn if running in a development environment.
     *
     * @return void
     */
    protected function warnIfDevelopment(): void
    {
        $env = $this->laravel->environment();

        if (in_array($env, ['local', 'development', 'dev'], true)) {
            $this->newLine();
            $this->warn('Warning: Caching in development environment is not recommended.');
            $this->warn('Configuration changes will require running cache commands again.');
        }
    }

    /**
     * Write verbose output if enabled.
     *
     * @param string $message The message to write.
     *
     * @return void
     */
    protected function verbose(string $message): void
    {
        if ($this->isVeryVerbose()) {
            $this->line("  <comment>{$message}</comment>");
        }
    }

    /**
     * Check if the output is very verbose.
     *
     * @return bool True if a very verbose mode is enabled.
     */
    private function isVeryVerbose(): bool
    {
        return $this->getOutput()->getVerbosity() >= 2;
    }
}
